// Calculate wave/depth for each task
// Wave 0: tasks with no dependencies
// Wave K: tasks whose deepest dependency is in wave K-1
function calculateWaves() {
  const depths = new Map()

  function getDepth(taskName) {
    if (depths.has(taskName)) {
