const NAME = /^[A-Za-z0-9_.-]+$/
const COST = /^[0-9]+$/

/**
 * Parse the input into { names, cost, deps }. `fail(message, code)` reports
 * the first failure and does not return.
 */
export function parseGraph(input, fail) {
  const lines = input.split('\n')
  if (lines.length > 0 && lines[lines.length - 1] === '') lines.pop()

  const cost = new Map()
  const deps = new Map() // name -> Set of dependency names
  const names = []
  const used = [] // every name a dep line mentions, in input order

  const edge = (from, to) => {
    let set = deps.get(from)
    if (!set) {
      set = new Set()
      deps.set(from, set)
    }
    set.add(to)
  }

  for (let i = 0; i < lines.length; i++) {
    const n = i + 1
    const text = lines[i].trim()
    if (text === '' || text.startsWith('#')) continue
    const words = text.split(/\s+/)

    if (words[0] === 'task') {
      if (words.length !== 3) fail(`error: line ${n}: expected task <name> <cost>`, 2)
      const name = words[1]
      if (!NAME.test(name)) fail(`error: line ${n}: invalid task name ${name}`, 2)
      if (!COST.test(words[2])) fail(`error: line ${n}: cost must be a non-negative integer`, 2)
      if (cost.has(name)) fail(`error: line ${n}: task ${name} is declared twice`, 2)
      cost.set(name, Number(words[2]))
      names.push(name)
      if (!deps.has(name)) deps.set(name, new Set())
    } else if (words[0] === 'dep') {
      if (words.length < 3) fail(`error: line ${n}: expected dep <name> <dependency>...`, 2)
      for (let w = 1; w < words.length; w++) {
        if (!NAME.test(words[w])) fail(`error: line ${n}: invalid task name ${words[w]}`, 2)
        used.push(words[w])
      }
      for (let w = 2; w < words.length; w++) edge(words[1], words[w])
