  const colour = new Map() // undefined = unseen, 1 = on stack, 2 = done
  for (const start of names.slice().sort(byName)) {
    if (colour.get(start) === 2) continue
    const path = [start]
    const stack = [{ name: start, at: 0 }]
    colour.set(start, 1)
    while (stack.length) {
      const top = stack[stack.length - 1]
      const list = adj.get(top.name)
      if (top.at < list.length) {
        const next = list[top.at++]
        const state = colour.get(next)
        if (state === 1) {
          const from = path.indexOf(next)
          return path.slice(from).concat([next])
        }
        if (state === undefined) {
          colour.set(next, 1)
          path.push(next)
          stack.push({ name: next, at: 0 })
        }
      } else {
        colour.set(top.name, 2)
        stack.pop()
        path.pop()
      }
    }
  }
  return null
}

/** Start, finish and depth of every task with unlimited workers. */
export function timings(names, cost, deps) {
  const start = new Map()
  const finish = new Map()
  const depth = new Map()
  for (const name of topological(names, deps)) {
    let s = 0
    let d = 0
    const list = deps.get(name)
    for (const dep of list) {
      if (finish.get(dep) > s) s = finish.get(dep)
      if (depth.get(dep) + 1 > d) d = depth.get(dep) + 1
    }
    start.set(name, s)
    finish.set(name, s + cost.get(name))
    depth.set(name, list.size === 0 ? 0 : d)
  }
  let total = 0
  for (const f of finish.values()) if (f > total) total = f
  return { start, finish, depth, total }
}

/** Longest chain of costs beginning at each task, counting its own cost. */
export function priorities(names, cost, deps) {
  const dependents = new Map()
  for (const n of names) dependents.set(n, [])
  for (const n of names) for (const d of deps.get(n)) dependents.get(d).push(n)

  const prio = new Map()
  const order = topological(names, deps).reverse()
  for (const name of order) {
    let best = 0
    for (const child of dependents.get(name)) {
      if (prio.get(child) > best) best = prio.get(child)
    }
    prio.set(name, cost.get(name) + best)
  }
  return prio
}

/** Dependencies before dependents. The graph is known to be acyclic here. */
function topological(names, deps) {
  const pending = new Map()
  const dependents = new Map()
  for (const n of names) {
    pending.set(n, deps.get(n).size)
    dependents.set(n, [])
  }
  for (const n of names) for (const d of deps.get(n)) dependents.get(d).push(n)

  const queue = names.filter((n) => pending.get(n) === 0)
  const order = []
  for (let i = 0; i < queue.length; i++) {
    const n = queue[i]
    order.push(n)
    for (const child of dependents.get(n)) {
      pending.set(child, pending.get(child) - 1)
      if (pending.get(child) === 0) queue.push(child)
    }
  }
  return order
}
