    out.push(`wave ${k}: ${wave.join(' ')}`)
  }
  out.push(`total ${total}`)
} else if (mode === 'explain') {
  for (const n of sorted) {
    out.push(`${n} start=${start.get(n)} finish=${finish.get(n)} depth=${depth.get(n)}`)
  }
  out.push(`total ${total}`)
