import { readFileSync } from 'fs'

// Read all stdin
const input = readFileSync(0, 'utf8')

// Parse arguments
const args = process.argv.slice(2)

if (args.length === 0) {
  process.stderr.write('error: usage: cli.js waves|explain|pack <workers>\n')
  process.exit(2)
}

const mode = args[0]

// Validate mode
if (mode !== 'waves' && mode !== 'explain' && mode !== 'pack') {
  process.stderr.write('error: usage: cli.js waves|explain|pack <workers>\n')
  process.exit(2)
}

// Parse worker count for pack mode
let workers = 0
if (mode === 'pack') {
  if (args.length < 2) {
    process.stderr.write('error: usage: cli.js waves|explain|pack <workers>\n')
    process.exit(2)
  }

  const workerStr = args[1]
  // Check for leading zeros (but "0" alone is invalid, needs to be at least 1)
  if (workerStr.match(/^0\d/) || workerStr === '0' || !/^\d+$/.test(workerStr)) {
    process.stderr.write('error: workers must be a positive integer\n')
    process.exit(2)
  }

  workers = parseInt(workerStr, 10)
  if (workers < 1) {
    process.stderr.write('error: workers must be a positive integer\n')
    process.exit(2)
  }
}

// Parse input
const lines = input.split('\n')
// Drop the empty tail a trailing newline leaves
if (lines.length > 0 && lines[lines.length - 1] === '') {
  lines.pop()
}

// Task map: name -> cost
const tasks = new Map()
const taskDeclarationLine = new Map() // name -> line number (1-based)
const dependencies = new Map() // name -> Set of dependency names

let lineNumber = 0

for (const line of lines) {
  lineNumber++

  // Trim and ignore empty lines or comments
  const trimmed = line.trim()
  if (trimmed === '' || trimmed.startsWith('#')) {
    continue
  }

  // Split on runs of whitespace
  const words = trimmed.split(/\s+/)

  if (words.length === 0) {
    continue
  }

  const directive = words[0]

  if (directive === 'task') {
    if (words.length !== 3) {
      process.stderr.write(`error: line ${lineNumber}: expected task <name> <cost>\n`)
      process.exit(2)
    }

    const name = words[1]
    const costStr = words[2]

    // Validate task name
    if (!/^[A-Za-z0-9_.\-]+$/.test(name)) {
      process.stderr.write(`error: line ${lineNumber}: invalid task name ${name}\n`)
      process.exit(2)
    }

    // Validate cost
    if (!/^\d+$/.test(costStr)) {
      process.stderr.write(`error: line ${lineNumber}: cost must be a non-negative integer\n`)
      process.exit(2)
    }

    // Check for duplicate
    if (tasks.has(name)) {
      process.stderr.write(`error: line ${lineNumber}: task ${name} is declared twice\n`)
      process.exit(2)
    }

    const cost = parseInt(costStr, 10)
    tasks.set(name, cost)
    taskDeclarationLine.set(name, lineNumber)
    if (!dependencies.has(name)) {
      dependencies.set(name, new Set())
    }
  } else if (directive === 'dep') {
    if (words.length < 2) {
      process.stderr.write(`error: line ${lineNumber}: expected dep <name> <dependency>...\n`)
      process.exit(2)
    }

    const name = words[1]
    // Skip checking name validity here, will check when validating dependencies

    for (let i = 2; i < words.length; i++) {
      const dep = words[i]
      if (!dependencies.has(name)) {
        dependencies.set(name, new Set())
      }
      dependencies.get(name).add(dep)
    }
  } else {
    process.stderr.write(`error: line ${lineNumber}: unknown directive ${directive}\n`)
    process.exit(2)
  }
}

// Validate that all referenced tasks exist
for (const [taskName, deps] of dependencies.entries()) {
  for (const dep of deps) {
    if (!tasks.has(dep)) {
      process.stderr.write(`error: unknown task ${dep}\n`)
      process.exit(2)
    }
  }
}

// Check for cycles using DFS
function detectCycles() {
  const taskNames = Array.from(tasks.keys()).sort()

  for (const startTask of taskNames) {
    const visited = new Set()
    const recursionStack = []

    function dfs(taskName) {
      if (recursionStack.includes(taskName)) {
        // Found a cycle
        const cycleStart = recursionStack.indexOf(taskName)
        const cycle = recursionStack.slice(cycleStart).concat([taskName])
        return cycle
      }

      if (visited.has(taskName)) {
        return null
      }

      visited.add(taskName)
      recursionStack.push(taskName)

      const deps = dependencies.get(taskName) || new Set()
      const depNames = Array.from(deps).sort()

      for (const dep of depNames) {
        const cycle = dfs(dep)
        if (cycle) {
          return cycle
        }
      }

      recursionStack.pop()
      return null
    }

    const cycle = dfs(startTask)
    if (cycle) {
      return cycle
    }
  }

  return null
}

const cycle = detectCycles()
if (cycle) {
  const cycleStr = cycle.join(' -> ')
  process.stderr.write(`error: cycle: ${cycleStr}\n`)
  process.exit(3)
}

// Calculate wave/depth for each task
// Wave 0: tasks with no dependencies
// Wave K: tasks whose deepest dependency is in wave K-1
function calculateWaves() {
  const depths = new Map()

  function getDepth(taskName) {
    if (depths.has(taskName)) {
      return depths.get(taskName)
    }

    const deps = dependencies.get(taskName) || new Set()
    if (deps.size === 0) {
      depths.set(taskName, 0)
      return 0
    }

    let maxDepth = -1
    for (const dep of deps) {
      maxDepth = Math.max(maxDepth, getDepth(dep))
    }

    const depth = maxDepth + 1
    depths.set(taskName, depth)
    return depth
  }

  for (const taskName of tasks.keys()) {
    getDepth(taskName)
  }

  return depths
}

const depths = calculateWaves()

// Group tasks by wave
function getWaves() {
  const waves = new Map()

  for (const [taskName, depth] of depths.entries()) {
    if (!waves.has(depth)) {
      waves.set(depth, [])
    }
    waves.get(depth).push(taskName)
  }

  // Sort tasks in each wave
  for (const wave of waves.values()) {
    wave.sort()
  }

  return waves
}

// Calculate start and finish times for each task (with unlimited workers)
function calculateTimes() {
  const startTimes = new Map()
  const finishTimes = new Map()

  function getFinish(taskName) {
    if (finishTimes.has(taskName)) {
      return finishTimes.get(taskName)
    }

    const cost = tasks.get(taskName)
    const deps = dependencies.get(taskName) || new Set()

    let start = 0
    if (deps.size > 0) {
      for (const dep of deps) {
        start = Math.max(start, getFinish(dep))
      }
    }

    startTimes.set(taskName, start)
    const finish = start + cost
    finishTimes.set(taskName, finish)
    return finish
  }

  for (const taskName of tasks.keys()) {
    getFinish(taskName)
  }

  return { startTimes, finishTimes }
}

const times = calculateTimes()

// Calculate makespan (unlimited workers)
function calculateMakespan() {
  let makespan = 0
  for (const finish of times.finishTimes.values()) {
    makespan = Math.max(makespan, finish)
  }
  return makespan
}

// Calculate priority for a task (longest chain from it going forward)
// Priority = cost of this task + max priority of tasks that depend on it
function calculatePriorities() {
  const priorities = new Map()
  const visited = new Set()

  function getPriority(taskName) {
    if (priorities.has(taskName)) {
      return priorities.get(taskName)
    }

    if (visited.has(taskName)) {
      return 0 // Avoid infinite recursion
    }

    visited.add(taskName)

    const cost = tasks.get(taskName)

    // Find all tasks that depend on this one
    let maxChain = 0
    for (const [name, deps] of dependencies.entries()) {
      if (deps.has(taskName)) {
        maxChain = Math.max(maxChain, getPriority(name))
      }
    }

    const priority = cost + maxChain
    priorities.set(taskName, priority)
    return priority
  }

  for (const taskName of tasks.keys()) {
    getPriority(taskName)
  }

  return priorities
}

// Execute the command
if (mode === 'waves') {
  const waves = getWaves()
  const maxWave = waves.size === 0 ? -1 : Math.max(...waves.keys())

  for (let i = 0; i <= maxWave; i++) {
    const waveTasksNames = waves.get(i) || []
    process.stdout.write(`wave ${i}: ${waveTasksNames.join(' ')}\n`)
  }

  const makespan = calculateMakespan()
  process.stdout.write(`total ${makespan}\n`)
} else if (mode === 'explain') {
  const taskNames = Array.from(tasks.keys()).sort()

  for (const taskName of taskNames) {
    const start = times.startTimes.get(taskName)
    const finish = times.finishTimes.get(taskName)
    const depth = depths.get(taskName)

    process.stdout.write(`${taskName} start=${start} finish=${finish} depth=${depth}\n`)
  }

  const makespan = calculateMakespan()
  process.stdout.write(`total ${makespan}\n`)
} else if (mode === 'pack') {
  // Simulate scheduling on workers
  const workerStates = Array.from({ length: workers }, () => ({
    freeAt: 0,
    tasks: []
  }))

  const priorities = calculatePriorities()
  const taskFinishTimes = new Map()

  function isReady(taskName, currentTime) {
    const deps = dependencies.get(taskName) || new Set()
    for (const dep of deps) {
      if (!taskFinishTimes.has(dep)) {
        return false
      }
      if (taskFinishTimes.get(dep) > currentTime) {
        return false
      }
    }
    return true
  }

  let currentTime = 0
  const allTasks = Array.from(tasks.keys())

  while (taskFinishTimes.size < allTasks.length) {
    // Find all ready tasks
    const readyTasks = []
    for (const taskName of allTasks) {
      if (!taskFinishTimes.has(taskName) && isReady(taskName, currentTime)) {
        readyTasks.push(taskName)
      }
    }

    // Sort by priority (descending), then by name (ascending)
    readyTasks.sort((a, b) => {
      const priorityDiff = priorities.get(b) - priorities.get(a)
      if (priorityDiff !== 0) return priorityDiff
      return a.localeCompare(b)
    })

    // Try to assign ready tasks to free workers
    let assigned = false
    for (const taskName of readyTasks) {
      // Find free worker with smallest index
      let freeWorker = -1
      for (let i = 0; i < workers; i++) {
        if (workerStates[i].freeAt <= currentTime) {
          freeWorker = i
          break
        }
      }

      if (freeWorker === -1) {
        break // No free worker at current time
      }

      const cost = tasks.get(taskName)
      const startTime = Math.max(currentTime, workerStates[freeWorker].freeAt)
      const finishTime = startTime + cost

      workerStates[freeWorker].tasks.push({ name: taskName, start: startTime, finish: finishTime })
      workerStates[freeWorker].freeAt = finishTime
      taskFinishTimes.set(taskName, finishTime)
      assigned = true
    }

    if (!assigned && taskFinishTimes.size < allTasks.length) {
      // Advance time to next instant when a worker becomes free
      let minFreeTime = Infinity
      for (const state of workerStates) {
        if (state.freeAt > currentTime) {
          minFreeTime = Math.min(minFreeTime, state.freeAt)
        }
      }
      if (minFreeTime === Infinity) {
        // No worker will be free later - shouldn't happen
        break
      }
      currentTime = minFreeTime
    }
  }

  // Output worker schedules
  let maxFinish = 0
  for (let i = 0; i < workers; i++) {
    const tasksStr = workerStates[i].tasks
      .map(t => `${t.name}@${t.start}-${t.finish}`)
      .join(' ')

    if (tasksStr) {
      process.stdout.write(`worker ${i}: ${tasksStr}\n`)
    } else {
      process.stdout.write(`worker ${i}:\n`)
    }

    if (workerStates[i].tasks.length > 0) {
      maxFinish = Math.max(maxFinish, workerStates[i].freeAt)
    }
  }

  process.stdout.write(`makespan ${maxFinish}\n`)
}

